    unique_count = 0
    for _ in range(Q):
        t = data[idx]
        if t == '1' or t == '2':
            x = int(data[idx + 1])
            if t == '1':
                if counts[x] == 0:
                    unique_count += 1
                counts[x] += 1
            else:
                counts[x] -= 1
                if counts[x] == 0:
                    unique_count -= 1
            idx += 2
        else:
            print(unique_count)
            idx += 1

